/// <summary>
/// CB166_SalesOrderSubstitutes
/// Processing a sales order for substitutes
/// </summary>
internal final class METSalesTableSubstituteProcess
{
    SalesTable  salesTable;
    METExcludeLinesWithManualReservation excludeLines;
    
}

Method.Source:
/// <summary>
/// Construct
/// </summary>
/// <param name = "_salesTable">Sales order header</param>
/// <param name = "_excludeLines">Exclude lines with manual reservation</param>
/// <returns>New instance of <c>METSalesTableSubstituteProcess</c> class</returns>
static METSalesTableSubstituteProcess construct(SalesTable _salesTable, METExcludeLinesWithManualReservation _excludeLines)
{
    if (!_salesTable)
    {
        throw error(strFmt("@SYS19306", funcName()));
    }
    
    return new METSalesTableSubstituteProcess(_salesTable, _excludeLines);
}

/// <summary>
/// New method
/// </summary>
/// <param name = "_salesTable">Sales order header</param>
/// <param name = "_excludeLines">Exclude lines with manual reservation</param>
protected void new(SalesTable _salesTable, METExcludeLinesWithManualReservation _excludeLines)
{
    salesTable = _salesTable;
    excludeLines = _excludeLines;
}

    /// <summary>
    /// Run the sales order substitute process
    /// </summary>
    void run()
    {
        boolean substituted;
        str substitutedString = "@MET:NotFound";
        
        setPrefix(strFmt("@MET:SubstituteSalesOrder", salesTable.SalesId));
        
        SalesLine salesLine;
        
        // If the Metcash sales order type does not allow for substitution, skip all of Step 2:  Processing for each line
        // and check if Step 3:  Update the order header to Ready for pricing is required.
        if (salesTable.METSalesOrderTypes().SubstitutesAllowed)
        {
            QueryRun qr = new QueryRun(this.initSalesLineQuery());

            while (qr.next())
            {
                salesLine = qr.get(tableNum(SalesLine));

                // Check if the line has any reservation at all (even if it is partial and not for the full quantity)
                if (!salesLine.mcrSalesQtyReserved())
                {
                    // Process salesLine for substitution
                    METSubstitutionSalesLineProcess substitutionSalesLineProcess = METSubstitutionSalesLineProcess::construct(salesLine, false, false);
                    substituted = substitutionSalesLineProcess.run();

                    if (substituted)
                    {
                        substitutedString = "@MET:Found";
                    }
                }
            }
        }

        // Step 3:  Update the order header to “Ready for pricing”
        // when this process is called from the “Post order creation batch”, the batch will set this “order processing status” instead of this Step 3,
        // as the batch must set the status for all orders whether substitutions are attempted or not.
        ttsbegin;
        METSalesTable metSalesTable = METSalesTable::findByRefRecId(salesTable.RecId, true);
        if (metSalesTable)
        {
            metSalesTable.OrderProcessingStatus = METSalesOrderProcessingStatus::ReadyForPricing;
            metSalesTable.update();
        }
        ttscommit;

        info(strFmt("@MET:ProcessedWithSubstituteRecord", substitutedString));
    }

    /// <summary>
    /// Initialise the sales order line query to substitute
    /// </summary>
    /// <returns><c>Query</c> object</returns>
    Query initSalesLineQuery()
    {
        Query query = new Query();
        QueryBuildDataSource qbds = query.addDataSource(tableNum(SalesLine));

        qbds.addRange(fieldNum(SalesLine, SalesId)).value(queryValue(salesTable.SalesId));

        // Exclude canceled lines
        qbds.addRange(fieldNum(SalesLine, SalesStatus)).value(SysQuery::valueNot(SalesStatus::Canceled));

        // Exclude manual reservation lines
        if (excludeLines)
        {
            qbds.addRange(fieldNum(SalesLine, Reservation)).value(SysQuery::valueNot(ItemReservation::None));
        }

        return query;
    }
